package vn.cineprime.admin;

import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.cineprime.domain.Store;
import vn.cineprime.booking.BookingService;
import static vn.cineprime.domain.Domain.*;

/** Setup progress is derived from existing records. No wizard state or money is stored here. */
@Service @Transactional(readOnly=true)
public class RoomSetup {
    private final Store db;private final Clock clock;private final BookingService booking;
    public RoomSetup(Store db,Clock clock,BookingService booking){this.db=db;this.clock=clock;this.booking=booking;}
    public record SeatInput(Long id,String label,String rowLabel,int position,String type,String coupleGroup,boolean active){}
    public boolean busy(Long room){return db.count(Showtime.class,"where e.roomId=?1 and (e.status='OPEN' or e.endsAt>?2)",room,clock.instant())>0;}
    private void require(boolean ok,String text){if(!ok)throw new IllegalArgumentException(text);}
    public Room room(Long cinema,Long room){Room r=db.get(Room.class,room);require(cinema==null||r.cinemaId.equals(cinema),"Phòng không thuộc rạp đang chọn.");return r;}
    public List<Map<String,Object>> seatViews(Long room){var seats=db.list(Seat.class,"where e.roomId=?1 order by e.rowLabel,e.position,e.id",room);Set<Long> referenced=new HashSet<>();if(!seats.isEmpty()){var ids=seats.stream().map(s->s.id).toList();for(Class<? extends Row> t:List.of(Inventory.class,OrderSeat.class,Ticket.class))referenced.addAll(db.query("select distinct x.seatId from "+db.entityName(t)+" x where x.seatId in ?1",Long.class,ids));}return seats.stream().map(s->{var v=db.view(s);boolean used=referenced.contains(s.id)||s.type.equals("COUPLE")&&seats.stream().anyMatch(p->Objects.equals(p.coupleGroup,s.coupleGroup)&&referenced.contains(p.id));v.put("typeLabel",type(s.type));v.put("canDelete",!used);v.put("deleteReason",used?"Ghế/cặp có lịch sử; chỉ được ngừng sử dụng khi phòng không khóa.":"Chỉ xóa khi Lưu sơ đồ; backend kiểm tra lại.");return v;}).toList();}
    public AdminPage<Map<String,Object>> shows(Long room,int requested){long total=db.count(Showtime.class,"where e.roomId=?1",room);int page=AdminPage.number(requested,total);var rows=db.entityManager().createQuery("select s,m.title from "+db.entityName(Showtime.class)+" s, "+db.entityName(Movie.class)+" m where s.movieId=m.id and s.roomId=?1 order by s.startsAt desc,s.id desc",Object[].class).setParameter(1,room).setFirstResult(page*5).setMaxResults(5).getResultList().stream().map(r->{Showtime s=(Showtime)r[0];return Map.<String,Object>of("id",s.id,"title",r[1]+" · "+db.date(s.startsAt),"status",AdminPresentation.text(s.status));}).toList();return new AdminPage<>(rows,total,page,page>0,(page+1L)*5<total);}
    public static String type(String code){return switch(code){case "STANDARD"->"Standard · Ghế thường";case "VIP"->"VIP";case "COUPLE"->"Couple · Ghế đôi";default->code;};}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public Map<String,Object> context(Long cinemaId,Long roomId){
        Room room=roomId==null?null:room(cinemaId,roomId);Long cinema=room==null?cinemaId:room.cinemaId;if(cinema!=null)db.get(Cinema.class,cinema);
        Map<String,Object> v=new LinkedHashMap<>();v.put("cinemaId",cinema==null?"":cinema);v.put("roomId",roomId==null?"":roomId);v.put("cinemaName",cinema==null?"Chọn rạp":db.get(Cinema.class,cinema).name);v.put("roomName",room==null?"":room.name);
        v.put("cinemas",db.list(Cinema.class,"order by e.name,e.id").stream().map(c->Map.of("id",c.id,"name",c.name,"active",c.active)).toList());v.put("rooms",cinema==null?List.of():db.list(Room.class,"where e.cinemaId=?1 order by e.name,e.id",cinema).stream().map(r->Map.of("id",r.id,"name",r.name,"active",r.active,"cinemaId",r.cinemaId)).toList());
        v.put("genres",db.list(Genre.class,"order by e.name,e.id").stream().map(g->Map.of("id",g.id,"name",g.name,"active",g.active)).toList());v.put("movies",db.list(Movie.class,"order by e.title,e.id").stream().map(m->Map.of("id",m.id,"title",m.title,"active",m.active,"status",m.status)).toList());
        var seats=room==null?List.<Seat>of():db.list(Seat.class,"where e.roomId=?1 order by e.rowLabel,e.position",roomId);v.put("seats",room==null?List.of():seatViews(roomId));v.put("totalSeats",seats.size());v.put("activeSeats",seats.stream().filter(s->s.active).count());v.put("pairs",seats.stream().filter(s->s.active&&s.type.equals("COUPLE")).count()/2);v.put("busy",room!=null&&busy(roomId));
        var types=seats.stream().filter(s->s.active).map(s->s.type).distinct().sorted().toList();v.put("seatTypes",types);v.put("counts",List.of("STANDARD","VIP","COUPLE").stream().map(t->Map.of("type",t,"label",type(t),"count",seats.stream().filter(s->s.active&&s.type.equals(t)).count())).toList());
        List<Price> prices=cinema==null?List.of():db.list(Price.class,"where e.cinemaId=?1 order by e.dayType,e.seatType,e.fromMinute",cinema);List<Map<String,Object>> days=new ArrayList<>();
        for(String day:List.of("WEEKDAY","WEEKEND")){List<Map<String,Object>> groups=new ArrayList<>();for(String t:types){var matching=prices.stream().filter(p->p.dayType.equals(day)&&p.seatType.equals(t)).toList();List<String> gaps=new ArrayList<>();int end=0;for(Price p:matching){if(p.fromMinute>end)gaps.add(AdminPresentation.time(end)+"–"+AdminPresentation.time(p.fromMinute));end=Math.max(end,p.toMinute);}if(end<1440)gaps.add(AdminPresentation.time(end)+"–24:00");groups.add(Map.of("type",t,"label",type(t),"rules",matching.size(),"gaps",gaps.isEmpty()?"Không có khoảng trống":String.join(", ",gaps)));}days.add(Map.of("code",day,"label",AdminPresentation.text(day),"groups",groups));}
        v.put("priceDays",days);v.put("currentDayType",clock.instant().atZone(ReportService.ZONE).getDayOfWeek().getValue()>=6?"WEEKEND":"WEEKDAY");v.put("priceCount",prices.size());v.put("version",room==null?"":version(roomId));return v;
    }
    public String version(Long room){Room r=db.get(Room.class,room);StringBuilder value=new StringBuilder(r.cinemaId+"|"+r.name+"|"+r.format+"|"+r.active);for(Seat s:db.list(Seat.class,"where e.roomId=?1 order by e.id",room))value.append('|').append(s.id).append(':').append(s.label).append(':').append(s.rowLabel).append(':').append(s.position).append(':').append(s.type).append(':').append(s.coupleGroup).append(':').append(s.active);try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    public AdminPage<Map<String,Object>> blockers(Long room,int requested){
        String where=" where s.roomId=?1 and (s.status='OPEN' or s.endsAt>?2)";String from=" from "+db.entityName(Showtime.class)+" s"+where;long total=db.query("select count(s)"+from,Long.class,room,clock.instant()).getFirst();int page=AdminPage.number(requested,total);
        var rows=db.entityManager().createQuery("select s,m.title from "+db.entityName(Showtime.class)+" s, "+db.entityName(Movie.class)+" m where s.movieId=m.id and s.roomId=?1 and (s.status='OPEN' or s.endsAt>?2) order by s.startsAt,s.id",Object[].class).setParameter(1,room).setParameter(2,clock.instant()).setFirstResult(page*5).setMaxResults(5).getResultList().stream().map(r->{Showtime s=(Showtime)r[0];return Map.<String,Object>of("id",s.id,"movie",r[1],"when",db.date(s.startsAt),"status",AdminPresentation.text(s.status),"cinemaId",db.get(Room.class,room).cinemaId,"day",s.startsAt.atZone(ReportService.ZONE).toLocalDate().toString());}).toList();return new AdminPage<>(rows,total,page,page>0,(page+1L)*5<total);
    }
    public Map<String,Object> readiness(Long cinema,Long roomId,Long movieId,Instant start,Long editingId){
        List<String> errors=new ArrayList<>();if(roomId==null||movieId==null||start==null)return Map.of("canOpen",false,"errors",List.of("Chọn đủ phim, rạp, phòng và giờ để kiểm tra mở bán."));
        Room room=room(cinema,roomId);Movie movie=db.get(Movie.class,movieId);if(!room.active||!db.get(Cinema.class,room.cinemaId).active||!movie.active||movie.status.equals("STOPPED"))errors.add("Phim/rạp/phòng đã ngừng hoạt động.");
        if(db.query("select count(g) from "+db.entityName(Genre.class)+" g, "+db.entityName(MovieGenre.class)+" x where x.genreId=g.id and x.movieId=?1 and g.active=true",Long.class,movieId).getFirst()==0)errors.add("Phim chưa có thể loại hoạt động. Bổ sung trong form phim trước khi mở bán.");
        Showtime proposed=new Showtime();proposed.roomId=roomId;proposed.movieId=movieId;proposed.startsAt=start;proposed.endsAt=start.plusSeconds(movie.duration*60L);
        var seats=db.list(Seat.class,"where e.roomId=?1 and e.active=true",roomId);if(seats.isEmpty())errors.add("Phòng chưa có ghế hoạt động.");
        try{validateCurrent(roomId);}catch(IllegalArgumentException e){errors.add(e.getMessage());}
        ZonedDateTime local=start.atZone(ReportService.ZONE);String day=local.getDayOfWeek().getValue()>=6?"WEEKEND":"WEEKDAY";int minute=local.getHour()*60+local.getMinute();
        for(String t:seats.stream().map(s->s.type).distinct().toList())if(db.count(Price.class,"where e.cinemaId=?1 and e.seatType=?2 and e.dayType=?3 and e.fromMinute<=?4 and e.toMinute>?4",room.cinemaId,t,day,minute)!=1)errors.add("Thiếu hoặc trùng giá "+type(t)+" tại giờ suất đang chọn.");
        Instant end=proposed.endsAt;if(editingId!=null){Showtime editing=db.get(Showtime.class,editingId);if(db.count(Order.class,"where e.showtimeId=?1 and (e.status='PAID' or (e.status='PENDING_PAYMENT' and e.expiresAt>?2))",editingId,clock.instant())>0)end=editing.endsAt;}
        if(db.count(Showtime.class,"where e.roomId=?1 and e.status<>'CANCELLED' and e.id<>?2 and e.startsAt<?3 and e.endsAt>?4",roomId,editingId==null?-1L:editingId,end.plusSeconds(900),start.minusSeconds(900))>0)errors.add("Trùng lịch phòng, gồm 15 phút vệ sinh.");
        return Map.of("canOpen",errors.isEmpty(),"errors",errors);
    }
    public void validateCurrent(Long room){validate(db.list(Seat.class,"where e.roomId=?1",room));}
    private void validate(List<Seat> seats){
        require(seats.size()<=600,"Sơ đồ tối đa 600 ghế.");Set<String> labels=new HashSet<>(),positions=new HashSet<>(),rows=new HashSet<>();Map<String,List<Seat>> pairs=new HashMap<>();
        for(Seat s:seats){require(s.label!=null&&!s.label.isBlank()&&s.label.length()<=30&&s.rowLabel!=null&&s.rowLabel.matches("[A-T]"),"Tên ghế và hàng A–T không hợp lệ.");require(s.position>=1&&s.position<=30,"Vị trí cột từ 1 đến 30.");require(labels.add(s.label)&&positions.add(s.rowLabel+":"+s.position),"Trùng tên hoặc vị trí ghế.");rows.add(s.rowLabel);require(Set.of("STANDARD","VIP","COUPLE").contains(s.type),"Loại ghế không hợp lệ.");if(s.type.equals("COUPLE")){require(s.coupleGroup!=null&&!s.coupleGroup.isBlank()&&s.coupleGroup.length()<=60,"Ghế Couple cần mã cặp.");pairs.computeIfAbsent(s.coupleGroup,k->new ArrayList<>()).add(s);}}
        require(rows.size()<=20,"Sơ đồ tối đa 20 hàng.");for(var pair:pairs.values())require(pair.size()==2&&pair.get(0).rowLabel.equals(pair.get(1).rowLabel)&&Math.abs(pair.get(0).position-pair.get(1).position)==1&&pair.get(0).active==pair.get(1).active,"Couple cần đúng hai ghế liền nhau cùng hàng và cùng trạng thái. Hãy sửa cả cặp.");
    }
    private void copy(Seat seat,SeatInput input,Long room){seat.roomId=room;seat.label=Objects.toString(input.label(),"").trim();seat.rowLabel=Objects.toString(input.rowLabel(),"").trim();seat.position=input.position();seat.type=Objects.toString(input.type(),"");seat.coupleGroup=seat.type.equals("COUPLE")?Objects.toString(input.coupleGroup(),"").trim():"";seat.active=input.active();}
    @Transactional public void create(Long actor,Long room,List<SeatInput> inputs){
        db.lock(Room.class,room);require(!busy(room)&&db.count(Seat.class,"where e.roomId=?1",room)==0,"Chỉ tạo sơ đồ cho phòng trống chưa có lịch.");require(inputs!=null&&!inputs.isEmpty()&&inputs.size()<=600,"Chọn từ 1 đến 600 ghế.");List<Seat> seats=new ArrayList<>();for(SeatInput input:inputs){require(input.id()==null,"Sơ đồ mới không nhận ID ghế cũ.");Seat s=new Seat();copy(s,input,room);seats.add(s);}validate(seats);seats.forEach(db::save);db.audit(actor,"GENERATE_LAYOUT",room.toString());
    }
    @Transactional public void create(Long actor,Long room,List<SeatInput> inputs,String expected){db.lock(Room.class,room);require(expected!=null&&expected.equals(version(room)),"Thông tin phòng/sơ đồ vừa thay đổi. Mở lại bước thiết lập trước khi lưu; bản xem trước chưa được ghi.");create(actor,room,inputs);}
    @Transactional public void change(Long actor,Long room,List<SeatInput> changes,List<Long> deletes){
        db.lock(Room.class,room);require(!busy(room),"Phòng có lịch đang khóa sơ đồ. Xem danh sách suất gây khóa.");require(changes!=null&&changes.size()<=600&&deletes!=null&&deletes.size()<=600,"Yêu cầu ghế không hợp lệ.");Set<Long> touched=new HashSet<>();
        for(Long id:deletes){require(touched.add(id),"Lặp ID ghế.");Seat s=db.lock(Seat.class,id);require(s.roomId.equals(room),"Ghế không thuộc phòng.");require(!referenced(id),"Ghế có lịch sử không thể xóa vĩnh viễn; chỉ được ngừng sử dụng.");db.delete(s);}db.entityManager().flush();
        for(SeatInput input:changes){Seat s=input.id()==null?new Seat():db.lock(Seat.class,input.id());if(input.id()!=null)require(touched.add(input.id())&&s.roomId.equals(room),"Ghế lặp hoặc không thuộc phòng.");copy(s,input,room);db.save(s);}validateCurrent(room);db.audit(actor,"UPDATE_LAYOUT",room.toString());
    }
    @Transactional public void change(Long actor,Long room,List<SeatInput> changes,List<Long> deletes,String expected){db.lock(Room.class,room);require(expected!=null&&expected.equals(version(room)),"Sơ đồ vừa được cập nhật ở nơi khác. Mở lại sơ đồ để tránh ghi đè; bản xem trước chưa được ghi.");change(actor,room,changes,deletes);}
    public boolean referenced(Long seat){return db.count(Inventory.class,"where e.seatId=?1",seat)>0||db.count(OrderSeat.class,"where e.seatId=?1",seat)>0||db.count(Ticket.class,"where e.seatId=?1",seat)>0;}
    @Transactional public void disable(Long actor,Long id){Seat seat=db.get(Seat.class,id);db.lock(Room.class,seat.roomId);require(!busy(seat.roomId),"Phòng có lịch đang khóa sơ đồ.");for(Seat s:db.list(Seat.class,"where e.roomId=?1",seat.roomId))if(s.id.equals(id)||seat.type.equals("COUPLE")&&s.type.equals("COUPLE")&&Objects.equals(s.coupleGroup,seat.coupleGroup))s.active=false;validateCurrent(seat.roomId);db.audit(actor,"DISABLE_SEATS",id.toString());}
    public Map<String,Object> inventory(Long roomId,Long showId){
        Room room=room(null,roomId);Showtime show=db.first(Showtime.class,"where e.id=?1",showId).orElseThrow(()->new IllegalArgumentException("Không tìm thấy suất chiếu."));require(show.roomId.equals(room.id),"Suất không thuộc phòng đang xem.");
        var rows=db.query("select i,s,o from "+db.entityName(Inventory.class)+" i join "+db.entityName(Seat.class)+" s on i.seatId=s.id left join "+db.entityName(Order.class)+" o on i.orderId=o.id where i.showtimeId=?1 order by s.rowLabel,s.position",Object[].class,showId).stream().map(r->{Inventory i=(Inventory)r[0];Seat s=(Seat)r[1];Order o=(Order)r[2];String state=!s.active?"MAINTENANCE":i.status.equals("HELD")&&(i.expiresAt==null||!clock.instant().isBefore(i.expiresAt))?"AVAILABLE":i.status;Map<String,Object> v=new LinkedHashMap<>(db.view(s));v.put("state",state);v.put("orderId",o==null?"":o.id);v.put("orderCode",o==null?"":o.code);v.put("canCancel",state.equals("HELD")&&o!=null&&o.status.equals("PENDING_PAYMENT"));return v;}).toList();
        return Map.of("seats",rows,"serverTime",clock.instant().toString(),"when",db.date(show.startsAt));
    }
}
